DROP TABLE IF EXISTS `go_down_product_details`;
CREATE TABLE `go_down_product_details` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `go_down_product_id` bigint(20) unsigned NOT NULL,
  `quantity` double NOT NULL,
  `unit_id` bigint(20) unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `go_down_product_details_godown_product_id_foreign` (`go_down_product_id`),
  KEY `go_down_product_details_unit_id_foreign` (`unit_id`),
  CONSTRAINT `go_down_product_details_godown_product_id_foreign` FOREIGN KEY (`go_down_product_id`) REFERENCES `go_down_products` (`id`) ON DELETE CASCADE,
  CONSTRAINT `go_down_product_details_unit_id_foreign` FOREIGN KEY (`unit_id`) REFERENCES `units` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=144 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

